#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> name(n);
    // (마감, 순번) 최소 힙
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
    for (int i = 0; i < n; i++) {
        int due;
        cin >> name[i] >> due;
        pq.push({due, i});
    }
    while (!pq.empty()) {
        auto [due, i] = pq.top();
        pq.pop();
        cout << due << ' ' << name[i] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct P {
    string name;
    int score;
};
struct Cmp {
    // true 면 a 가 b 보다 나중에 나온다
    bool operator()(const P& a, const P& b) const {
        if (a.score != b.score) return a.score < b.score;
        return a.name > b.name;
    }
};

int main() {
    priority_queue<P, vector<P>, Cmp> pq;
    pq.push({"kim", 80});
    pq.push({"lee", 95});
    pq.push({"choi", 80});
    pq.push({"park", 95});
    while (!pq.empty()) {
        cout << pq.top().name << ' ' << pq.top().score << '\n';
        pq.pop();
    }
    return 0;
}
